class Solution {
  public int minAdjacentSwaps(int[] nums, int a, int b) {
    long[] seen = new long[3];
    long inversions = 0;
    for (int v : nums) {
      int type = v < a ? 0 : v <= b ? 1 : 2;
      for (int t = type + 1; t < 3; t++) inversions += seen[t];
      seen[type]++;
    }
    return (int) (inversions % 1_000_000_007L);
  }
}
